/**
 * Adopts the UIKit scene life cycle on iOS.
 *
 * The iOS 27 SDK asserts at launch unless the app adopts the scene-based life cycle
 * (`_UIApplicationEvaluateRuntimeIssueForNoSceneLifecycleAdoption`), and the Expo prebuild
 * template still generates the app-delegate life cycle. Expo ships the pieces from SDK 57.0.23
 * (`ExpoAppSceneDelegate`, `ExpoReactNativeFactoryProvider`) but leaves the wiring opt-in, so this
 * plugin does the wiring at prebuild time. See docs/bugs/crash-log.md.
 *
 * Three changes, all to generated files (ios/ is never edited by hand):
 *  1. a SceneDelegate.swift subclassing Expo's scene delegate, added to the app target,
 *  2. the scene manifest in Info.plist naming it,
 *  3. the AppDelegate conforming to ExpoReactNativeFactoryProvider and no longer creating the
 *     window itself, because the scene delegate now creates it and starts React Native into it.
 *
 * Remove this plugin once Expo's template adopts the scene life cycle on its own.
 */
const fs = require('fs');
const path = require('path');
const {
  IOSConfig,
  withAppDelegate,
  withInfoPlist,
  withXcodeProject,
} = require('expo/config-plugins');

const SCENE_DELEGATE_CLASS = 'SceneDelegate';
const SCENE_DELEGATE_FILENAME = `${SCENE_DELEGATE_CLASS}.swift`;

const SCENE_DELEGATE_SOURCE = `// Generated by the with-ios-scene-lifecycle config plugin. Do not edit by hand.
//
// The iOS 27 SDK requires the scene life cycle. ExpoAppSceneDelegate creates the window from the
// connecting UIWindowScene, starts React Native into it, and forwards scene, URL, Handoff and
// quick-action events to the app delegate. Info.plist names this class as the scene delegate.

internal import Expo
import UIKit

@objc(${SCENE_DELEGATE_CLASS})
class ${SCENE_DELEGATE_CLASS}: ExpoAppSceneDelegate {}
`;

/** Fail loudly at prebuild rather than shipping an app that traps at launch. */
function replaceOnce(contents, anchor, replacement, what) {
  const occurrences = contents.split(anchor).length - 1;
  if (occurrences !== 1) {
    throw new Error(
      `with-ios-scene-lifecycle: expected exactly one ${what} in AppDelegate.swift, found ${occurrences}. ` +
        `The Expo template changed; update the plugin (see docs/bugs/crash-log.md).`
    );
  }
  return contents.replace(anchor, replacement);
}

const withSceneDelegateFile = (config) =>
  withXcodeProject(config, (config) => {
    const projectRoot = config.modRequest.projectRoot;
    const appDelegatePath = IOSConfig.Paths.getAppDelegateFilePath(projectRoot);
    const targetDir = path.dirname(appDelegatePath);
    const groupName = path.basename(targetDir);

    fs.writeFileSync(path.join(targetDir, SCENE_DELEGATE_FILENAME), SCENE_DELEGATE_SOURCE);

    const relativePath = `${groupName}/${SCENE_DELEGATE_FILENAME}`;
    if (!config.modResults.hasFile(relativePath)) {
      IOSConfig.XcodeUtils.addBuildSourceFileToGroup({
        filepath: relativePath,
        groupName,
        project: config.modResults,
        projectRoot,
      });
    }
    return config;
  });

const withSceneManifest = (config) =>
  withInfoPlist(config, (config) => {
    config.modResults.UIApplicationSceneManifest = {
      UIApplicationSupportsMultipleScenes: false,
      UISceneConfigurations: {
        UIWindowSceneSessionRoleApplication: [
          {
            UISceneConfigurationName: 'Default Configuration',
            UISceneDelegateClassName: SCENE_DELEGATE_CLASS,
          },
        ],
      },
    };
    return config;
  });

const withSceneAwareAppDelegate = (config) =>
  withAppDelegate(config, (config) => {
    let contents = config.modResults.contents;
    if (contents.includes('ExpoReactNativeFactoryProvider')) {
      return config;
    }

    contents = replaceOnce(
      contents,
      'class AppDelegate: ExpoAppDelegate {',
      'class AppDelegate: ExpoAppDelegate, ExpoReactNativeFactoryProvider {',
      'AppDelegate class declaration'
    );

    // The scene delegate owns the window under the scene life cycle; starting React Native here
    // as well would build a second, scene-less window and render nothing.
    contents = replaceOnce(
      contents,
      `#if os(iOS) || os(tvOS)
    window = UIWindow(frame: UIScreen.main.bounds)
    factory.startReactNative(
      withModuleName: "main",
      in: window,
      launchOptions: launchOptions)
#endif`,
      `    // The window is created and React Native is started by SceneDelegate, which UIKit
    // instantiates from the scene manifest in Info.plist.`,
      'window setup block'
    );

    config.modResults.contents = contents;
    return config;
  });

module.exports = function withIosSceneLifecycle(config) {
  return withSceneAwareAppDelegate(withSceneManifest(withSceneDelegateFile(config)));
};
